data.applications-connectivity-lab.json:
{
  "uid": "applications-connectivity-lab",
  "title": "Aplicações | Logs e conexões",
  "schemaVersion": 39,
  "version": 0,
  "timezone": "browser",
  "time": {
    "from": "now-1h",
    "to": "now"
  },
  "refresh": "30s",
  "tags": [
    "cosmotech",
    "apm",
    "logs"
  ],
  "panels": [
    {
      "id": 1,
      "type": "text",
      "title": "Conexões reais a cada 5 minutos",
      "gridPos": {
        "x": 0,
        "y": 0,
        "w": 24,
        "h": 4
      },
      "options": {
        "mode": "markdown",
        "content": "Cada pod faz chamada interna ao serviço par e GET HTTPS em `example.com` a cada **300 segundos**. Uma Lambda fora da VPC chama os dois hosts públicos pelo Scheduler. Logs JSON incluem status, duração e trace ID. As chamadas sintéticas não criam pedidos.\n\nOs spans estão no Tempo e no APM do Zabbix; use o `trace_id` do log para correlacionar. Os contadores abaixo mostram os últimos 15 minutos."
      }
    },
    {
      "id": 2,
      "type": "stat",
      "title": "orders-api • internal HTTP 200",
      "datasource": {
        "type": "loki",
        "uid": "loki"
      },
      "gridPos": {
        "x": 0,
        "y": 4,
        "w": 6,
        "h": 4
      },
      "targets": [
        {
          "refId": "A",
          "expr": "sum(count_over_time({namespace=\"orders-api\",container=\"orders-api\"} | json | event=\"synthetic_connection\" | direction=\"internal\" | status_code=200 | __error__=\"\" [15m]))",
          "queryType": "instant"
        }
      ],
      "options": {
        "reduceOptions": {
          "calcs": [
            "lastNotNull"
          ],
          "values": false
        },
        "graphMode": "none",
        "colorMode": "value"
      },
      "fieldConfig": {
        "defaults": {
          "unit": "short",
          "decimals": 0,
          "noValue": "Sem dados"
        },
        "overrides": []
      }
    },
    {
      "id": 3,
      "type": "stat",
      "title": "orders-api • external HTTP 200",
      "datasource": {
        "type": "loki",
        "uid": "loki"
      },
      "gridPos": {
        "x": 6,
        "y": 4,
        "w": 6,
        "h": 4
      },
      "targets": [
        {
          "refId": "A",
          "expr": "sum(count_over_time({namespace=\"orders-api\",container=\"orders-api\"} | json | event=\"synthetic_connection\" | direction=\"external\" | status_code=200 | __error__=\"\" [15m]))",
          "queryType": "instant"
        }
      ],
      "options": {
        "reduceOptions": {
          "calcs": [
            "lastNotNull"
          ],
          "values": false
        },
        "graphMode": "none",
        "colorMode": "value"
      },
      "fieldConfig": {
        "defaults": {
          "unit": "short",
          "decimals": 0,
          "noValue": "Sem dados"
        },
        "overrides": []
      }
    },
    {
      "id": 4,
      "type": "stat",
      "title": "orders-worker • internal HTTP 200",
      "datasource": {
        "type": "loki",
        "uid": "loki"
      },
      "gridPos": {
        "x": 12,
        "y": 4,
        "w": 6,
        "h": 4
      },
      "targets": [
        {
          "refId": "A",
          "expr": "sum(count_over_time({namespace=\"orders-worker\",container=\"orders-worker\"} | json | event=\"synthetic_connection\" | direction=\"internal\" | status_code=200 | __error__=\"\" [15m]))",
          "queryType": "instant"
        }
      ],
      "options": {
        "reduceOptions": {
          "calcs": [
            "lastNotNull"
          ],
          "values": false
        },
        "graphMode": "none",
        "colorMode": "value"
      },
      "fieldConfig": {
        "defaults": {
          "unit": "short",
          "decimals": 0,
          "noValue": "Sem dados"
        },
        "overrides": []
      }
    },
    {
      "id": 5,
      "type": "stat",
      "title": "orders-worker • external HTTP 200",
      "datasource": {
        "type": "loki",
        "uid": "loki"
      },
      "gridPos": {
        "x": 18,
        "y": 4,
        "w": 6,
        "h": 4
      },
      "targets": [
        {
          "refId": "A",
          "expr": "sum(count_over_time({namespace=\"orders-worker\",container=\"orders-worker\"} | json | event=\"synthetic_connection\" | direction=\"external\" | status_code=200 | __error__=\"\" [15m]))",
          "queryType": "instant"
        }
      ],
      "options": {
        "reduceOptions": {
          "calcs": [
            "lastNotNull"
          ],
          "values": false
        },
        "graphMode": "none",
        "colorMode": "value"
      },
      "fieldConfig": {
        "defaults": {
          "unit": "short",
          "decimals": 0,
          "noValue": "Sem dados"
        },
        "overrides": []
      }
    },
    {
      "id": 6,
      "type": "logs",
      "title": "Chamadas internas, externas e recebidas • logs correlacionados",
      "datasource": {
        "type": "loki",
        "uid": "loki"
      },
      "gridPos": {
        "x": 0,
        "y": 8,
        "w": 24,
        "h": 14
      },
      "targets": [
        {
          "refId": "A",
          "expr": "{namespace=~\"orders-api|orders-worker\",container=~\"orders-api|orders-worker\"} | json | event=~\"synthetic_.*\"",
          "queryType": "range",
          "maxLines": 1000
        }
      ],
      "options": {
        "showTime": true,
        "showLabels": false,
        "enableLogDetails": true,
        "wrapLogMessage": true,
        "dedupStrategy": "none",
        "sortOrder": "Descending"
      }
    },
    {
      "id": 7,
      "type": "timeseries",
      "title": "Duração das conexões",
      "datasource": {
        "type": "loki",
        "uid": "loki"
      },
      "gridPos": {
        "x": 0,
        "y": 22,
        "w": 24,
        "h": 8
      },
      "targets": [
        {
          "refId": "A",
          "expr": "avg by(service,direction) (avg_over_time({namespace=~\"orders-api|orders-worker\",container=~\"orders-api|orders-worker\"} | json | event=\"synthetic_connection\" | unwrap duration_ms | __error__=\"\" [5m]))",
          "queryType": "range",
          "legendFormat": "{{service}} • {{direction}}"
        }
      ],
      "fieldConfig": {
        "defaults": {
          "unit": "ms"
        },
        "overrides": []
      },
      "options": {
        "legend": {
          "displayMode": "list",
          "placement": "bottom"
        }
      }
    }
  ],
  "links": [
    {
      "type": "link",
      "title": "Command Center",
      "url": "/d/command-center"
    },
    {
      "type": "link",
      "title": "Zabbix AWS EKS e APM",
      "url": "https://zabbix.cosmotechsolutions.com.br/zabbix.php?action=dashboard.view&dashboardid=439",
      "targetBlank": true
    }
  ]
}

