{
  "title": "EKS - Infrastructure Overview",
  "uid": "eks-infrastructure-lab",
  "schemaVersion": 39,
  "version": 1,
  "refresh": "30s",
  "time": {"from": "now-1h", "to": "now"},
  "panels": [
    {
      "id": 1,
      "title": "CPU Usage by Node",
      "type": "timeseries",
      "gridPos": {"x":0,"y":0,"w":12,"h":8},
      "targets": [
        {"expr":"100 * (1 - avg by (instance) (rate(node_cpu_seconds_total{mode=\"idle\"}[5m])))","legendFormat":"{{instance}}"}
      ]
    },
    {
      "id": 2,
      "title": "Memory Usage by Node",
      "type": "timeseries",
      "gridPos": {"x":12,"y":0,"w":12,"h":8},
      "targets": [
        {"expr":"100 * (1 - node_memory_MemAvailable_bytes / node_memory_MemTotal_bytes)","legendFormat":"{{instance}}"}
      ]
    },
    {
      "id": 3,
      "title": "Pods by Namespace",
      "type": "timeseries",
      "gridPos": {"x":0,"y":8,"w":12,"h":8},
      "targets": [
        {"expr":"sum by (namespace) (kube_pod_info)","legendFormat":"{{namespace}}"}
      ]
    },
    {
      "id": 4,
      "title": "Pod Restarts",
      "type": "timeseries",
      "gridPos": {"x":12,"y":8,"w":12,"h":8},
      "targets": [
        {"expr":"sum by (namespace,pod) (increase(kube_pod_container_status_restarts_total[15m]))","legendFormat":"{{namespace}} / {{pod}}"}
      ]
    },
    {
      "id": 5,
      "title": "Istio Requests per Second",
